139	        "pratika_iast": "ebhiriti",
140	        "matches_verse": false,
141	        "content_containment": 0.3,
142	        "content_anchor": true
143	      },
144	      "tilaka": {
145	        "pratika_iast": "bhrukutin vakre bhruvau",
146	        "matches_verse": true
147	      }
148	    }
