168	        "matches_verse": true
169	      }
170	    }
171	  },
172	  {
173	    "verse_id": "5.63.10",
174	    "sarga": 63,
175	    "verse": "10",
176	    "ambiguous_marker": false,
177	    "sanskrit_iast": "tatas tair bahubhir vīrair vānarair vānararṣabhāḥ । saṃraktanayanaiḥ krodhād dharayaḥ sampracālitāḥ ॥10॥",
178	    "leonov_ru": "Затем теми многочисленными отважными обезьянами, чьи глаза покраснели от гнева, Обезьяны (стражи леса), быки между обезьянами, были обращены в бегство.",
179	    "commentary": {
180	      "bhusana": "ततस्तैर्बहुभिर्वीरैर्वानरैर्वानरर्षभः ।\n\nसंरक्तनयनैः क्रोधाद्धरयः प्रविचालिताः\nतत इत्यादि । उद्विग्नहृदयः भीतहृदयः । मातुलस्यापि पादपतनं स्वामित्वानुसारेण\nएवमुक्तस्तु सुग्रीवो लक्ष्मणेन महात्मना ।\n\nलक्ष्मणं प्रत्युवाचेदं वाक्यं वाक्यविशारदः",
181	      "siromani": "तदेव भङ्ग्यन्तरेणाह तत इति । हरयः मदनुयायिवानराः बहुभिस्तैर्वानरैः संप्रधर्षिताः"
182	    },
